<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $proyectos = Illuminate\Support\Facades\DB::table("proyectos")->where("ejercicio_id", 2026)->get(); foreach($proyectos as $p) { $acciones = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("proyecto_id", $p->proyecto_id)->get(); foreach($acciones as $a) { $riesgos = Illuminate\Support\Facades\DB::table("actividad_riesgo")->where("actividad_sustantiva_id", $a->id)->get(); if($riesgos->count() > 0) { echo "Found " . $riesgos->count() . " risks for action " . $a->id . "\n"; } } }
